INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(1,'hero",13,0);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(1,'id",'THE ART OF GATHERING",'Where Fire Meets Flavor.",'Perpaduan cita rasa, kehangatan, dan pengalaman bersantap yang tak terlupakan.",'Jelajahi Menu",'Temukan Kami");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(1,'en",'THE ART OF GATHERING",'Where Fire Meets Flavor.",'A meeting of flavor, warmth, and an unforgettable dining experience.",'Explore Menu",'Find Us");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(2,'about",17,1);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(2,'id",'KISAH KAMI",'Lebih dari sekadar tempat bersantap.",'OPENFIRE hadir sebagai sebuah imajinasi tentang ruang, rasa, dan kebersamaan. Berpadu dengan sentuhan arsitektur tropis dan kehangatan material alami, setiap sudut dirancang untuk mengundang Anda menikmati momen dengan lebih perlahan.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(2,'en",'OUR STORY",'More than just a place to dine.",'OPENFIRE is a vision of space, taste, and togetherness. Shaped by tropical architecture and the warmth of natural materials, every corner invites you to slow down and enjoy the moment.",'",'");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(3,'feature_fire",12,2);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(3,'id",'A SIGNATURE EXPERIENCE",'Berawal dari api. Berakhir dalam kenangan.",'Hidangan berkarakter, suasana yang mengundang, dan perhatian pada setiap detail — sebuah cara baru menikmati waktu bersama.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(3,'en",'A SIGNATURE EXPERIENCE",'Born of fire. Remembered for flavor.",'Distinctive dishes, welcoming spaces, and attention to every detail — a new way to savor time together.",'",'");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(4,'feature_space",14,3);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(4,'id",'ARCHITECTURE & AMBIENCE",'Ruang yang hidup bersama cerita.",'Cahaya hangat, tekstur alami, dan sentuhan hijau tropis menciptakan latar yang tenang untuk percakapan panjang dan pertemuan yang berarti.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(4,'en",'ARCHITECTURE & AMBIENCE",'A space for stories to unfold.",'Warm light, natural textures, and tropical greenery create a peaceful setting for meaningful gatherings and unhurried conversations.",'",'");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(5,'menu_intro",9,4);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(5,'id",'CURATED SELECTIONS",'Jelajahi rasa yang istimewa.",'Dari sajian favorit hingga pilihan minuman yang menyegarkan, temukan inspirasi untuk setiap momen bersantap.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(5,'en",'CURATED SELECTIONS",'Explore distinctive flavors.",'From comforting favorites to refreshing drinks, discover something to suit every dining moment.",'",'");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(6,'gallery_intro",15,5);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(6,'id",'SPACES & MOMENTS",'Keindahan ada dalam setiap sudut.",'Jelajahi permainan cahaya, detail arsitektur, dan sudut-sudut yang membuat OPENFIRE terasa istimewa.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(6,'en",'SPACES & MOMENTS",'Beauty lives in every detail.",'Discover warm light, architectural details, and the corners that make OPENFIRE feel special.",'",'");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(7,'location_intro",19,6);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(7,'id",'FIND YOUR WAY",'Temukan Kami.",'Temukan lokasi demonstrasi kami dan jelajahi rute menuju OPENFIRE.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(7,'en",'FIND YOUR WAY",'Find Us.",'Explore our demo location and discover the route to OPENFIRE.",'",'");
INSERT IGNORE INTO page_sections(id,slug,media_id,sort_order) VALUES(8,'contact_intro",21,7);
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(8,'id",'LET’S CONNECT",'Cerita indah dimulai dari percakapan.",'Punya pertanyaan tentang hidangan atau konsep restoran kami? Mari terhubung melalui WhatsApp.",'",'");
INSERT IGNORE INTO section_translations(section_id,lang,eyebrow,title,body,button_label,button_label_secondary) VALUES(8,'en",'LET’S CONNECT",'Great stories begin with a conversation.",'Have a question about our dishes or restaurant concept? Reach out to us on WhatsApp.",'",'");
